    record1.set("faq", [{"question": "What does EMI stand for?", "answer": "EMI stands for Equated Monthly Installment\u2014the fixed amount you pay monthly to repay a loan, including both principal and interest."}, {"question": "How is EMI calculated?", "answer": "EMI is calculated using the formula: EMI = [P \u00d7 R \u00d7 (1+R)^N] / [(1+R)^N - 1], where P is principal, R is monthly interest rate, and N is number of months."}, {"question": "Can I reduce my EMI?", "answer": "Yes, you can reduce EMI by increasing the loan tenure (though this increases total interest) or by making prepayments to reduce the principal amount."}]);
